import type { Pipeline, ProviderId } from "./schema.ts";

/**
 * One generated file: a repository-relative POSIX path and its full content.
 */
export interface EmittedFile {
  readonly path: string;
  readonly content: string;
}

export interface CompileOptions {
  /** Stable label for the pipeline's source (normally its repository-relative path), written into the generated header so the file says where it came from. */
  readonly source: string;
  /** The command that invokes this tool's CLI on the machine that will run the generated file (for example `node packages/cli/src/bin.ts`). Required when any job renders in the `wrapper` form, which calls it; ignored otherwise. */
  readonly toolCommand?: string;
  readonly signal?: AbortSignal;
}

/**
 * Compiles a validated pipeline into a provider's native configuration files.
 *
 * Pre: `pipeline` has passed `pipelineSchema`. Post: the output is deterministic (same input, byte-identical files), carries a generated header, and never contains a timestamp or other value that varies between runs. Errors: throws `UnsupportedFeatureError` when the model uses something the provider cannot express; it never drops or approximates it.
 */
export interface PipelineCompiler {
  readonly provider: ProviderId;
  compile: (pipeline: Pipeline, options: CompileOptions) => Promise<readonly EmittedFile[]>;
  /**
   * For each job id, the names under which this provider reports it as a check, one per matrix combination. A branch ruleset's required checks are matched against these, so they are what check-name derivation is built from. Throws `UnsupportedFeatureError` where `compile` would.
   */
  checkNames: (pipeline: Pipeline) => ReadonlyMap<string, readonly string[]>;
}

/**
 * The header every emitted file starts with, as comment lines without the provider's comment marker.
 */
export function generatedHeaderLines(source: string): string[] {
  return [
    `Generated from ${source} by pipewright. Do not edit this file by hand.`,
    "Regenerate it with the emit command; the check command fails when it drifts.",
  ];
}

export interface Drift {
  readonly path: string;
  readonly kind: "missing" | "changed";
}

/**
 * Compares freshly emitted files with what is on disk. `read` returns a file's current content, or `undefined` when it does not exist; it is injected so this stays free of any filesystem.
 */
export async function diffEmitted(
  expected: readonly EmittedFile[],
  read: (path: string) => Promise<string | undefined>,
): Promise<Drift[]> {
  const found = await Promise.all(
    expected.map(async (file): Promise<Drift | undefined> => {
      const actual = await read(file.path);
      if (actual === undefined) return { path: file.path, kind: "missing" };

      return actual === file.content ? undefined : { path: file.path, kind: "changed" };
    }),
  );

  return found.filter((entry): entry is Drift => entry !== undefined);
}
